using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace V15Voice {
public sealed class AnchorStage {
 public int Number;public bool FallbackBoundary;public List<Cue> Cues=new List<Cue>();
 public double Start{get{return Cues.First().Start;}}public double End{get{return Cues.Last().End;}}public double Budget{get{return End-Start;}}public string Text{get{return String.Join(" ",Cues.Select(c=>c.Text.Trim()));}}
}
public sealed class AnchorUnit {public int Stage;public double Start,End,StageStart,StageEnd;public string Text;}
public sealed class AnchorFit {public Wave Audio;public double Natural,Speed,Measured,SampleAdjustment;public bool Success;public string Reason="";}
public sealed class AnchorStageResult {public AnchorStage Stage;public AnchorFit Fit;}
public sealed class AnchorReport {
 public double Target;public bool Complete;public string Wav="",Srt="",AlignmentNote="";public List<AnchorStageResult> Stages=new List<AnchorStageResult>();public List<AnchorUnit> Units=new List<AnchorUnit>();
 public bool NeedsReview{get{return Stages.Any(s=>!s.Fit.Success||s.Stage.FallbackBoundary)||!String.IsNullOrEmpty(AlignmentNote);}}
 public string Summary{get{return (Complete?"WAV xong":"Chưa xuất WAV")+" · "+Scripts.Stamp(Target)+" · "+Stages.Count+" chặng"+(NeedsReview?" · cần duyệt":"");}}
 public string Describe(){var lines=new List<string>{Summary,"Căn theo thời lượng âm thanh thực, giữ đầu/cuối từng chặng; không đổi lời hoặc mốc SRT nguồn.","Mốc tự chia dựa trên dấu câu và khoảng nghỉ, không suy đoán cảnh video.",""};foreach(var r in Stages)lines.Add("Chặng "+r.Stage.Number+" · cue "+r.Stage.Cues.First().Id+"–"+r.Stage.Cues.Last().Id+" · "+Scripts.Stamp(r.Stage.Start)+" → "+Scripts.Stamp(r.Stage.End)+"\r\n  Giọng gốc "+r.Fit.Natural.ToString("0.000")+"s / khung "+r.Stage.Budget.ToString("0.000")+"s · tốc độ "+r.Fit.Speed.ToString("0.000")+" · "+(r.Fit.Success?"Đạt · hiệu chỉnh đuôi "+r.Fit.SampleAdjustment.ToString("+0.000;-0.000;0")+"s":r.Fit.Reason)+(r.Stage.FallbackBoundary?" · chặng dài, nên đặt neo ở cuối câu":""));lines.Add(String.IsNullOrEmpty(Srt)?"Chưa có SRT căn theo từ. Mốc chia đơn vị đọc chỉ là cửa sổ tìm kiếm, không phải mốc từ đã đo.":"SRT theo WAV: "+Srt);if(AlignmentNote.Length>0)lines.Add(AlignmentNote);return String.Join("\r\n",lines);}
}
public static class AnchoredVoice {
 public static void ConfigureBatch(RenderOptions o,bool timed,int batchMode,int timelineMode){o.Prose=!timed;o.Anchored=timed&&(batchMode==3||(batchMode==0&&timelineMode==2));o.Locked=timed&&!o.Anchored&&(batchMode==0||batchMode==1);o.AnchorResult=null;}
 public static List<AnchorStage> Plan(List<Cue> cues){Scripts.Validate(cues);if(cues.Any(c=>c.Prose))throw new Exception("V15.6 cần SRT có timeline nguồn; TXT dùng chế độ đọc tự nhiên.");var result=new List<AnchorStage>();var stage=new AnchorStage{Number=1};for(int i=0;i<cues.Count;i++){var c=cues[i];stage.Cues.Add(c);bool last=i==cues.Count-1,gap=!last&&cues[i+1].Start-c.End>=.75,stop=Regex.IsMatch(c.Text.TrimEnd(),"[.!?][\"”')\\]]?$"),clause=Regex.IsMatch(c.Text.TrimEnd(),"[,;:][\"”')\\]]?$");bool natural=last||c.AnchorAfter||gap||(stop&&stage.Budget>=12)||(clause&&stage.Budget>=30);if(natural||stage.Budget>=60){stage.FallbackBoundary=!natural;result.Add(stage);stage=new AnchorStage{Number=result.Count+1};}}return result;}
 public static string Inspect(List<Cue> cues){var stages=Plan(cues);return "V15.6 · giữ thời lượng nguồn "+Scripts.Stamp(cues.Last().End)+"\r\nGộp cue hiển thị thành câu đọc; đo giọng và tự căn tốc độ theo chặng. Đặt Khóa cuối chặng để bảo vệ điểm neo quan trọng.\r\nKhông áp dụng giới hạn 10 từ/cue. Chưa đo giọng thì chưa thể kết luận khung đọc vừa hay thiếu.\r\n\r\n"+String.Join("\r\n",stages.Select(s=>"Chặng "+s.Number+" · cue "+s.Cues.First().Id+"–"+s.Cues.Last().Id+" · "+Scripts.Stamp(s.Start)+" → "+Scripts.Stamp(s.End)+" · "+s.Cues.Sum(c=>c.Words)+" từ"+(s.FallbackBoundary?" · nên đặt neo ở cuối câu":"")));}
 public static List<string> SpeechUnits(string text){var result=new List<string>();foreach(var sentence in LongText.Parse(text)){string rest=sentence.Text.Trim();while(rest.Length>360){int cut=-1;for(int i=359;i>=120;i--)if(",;:—".IndexOf(rest[i])>=0&&i+1<rest.Length&&Char.IsWhiteSpace(rest[i+1])){cut=i+1;break;}if(cut<0)cut=rest.LastIndexOf(' ',359);if(cut<1)throw new Exception("Có từ dài quá 360 ký tự; kiểm tra văn bản.");result.Add(rest.Substring(0,cut).Trim());rest=rest.Substring(cut).Trim();}if(rest.Length>0)result.Add(rest);}return result;}
 public static AnchorFit Fit(Wave original,double target,RenderOptions o,string root,string work,Func<bool> cancel){Tempo.Validate(o);if(Double.IsNaN(target)||Double.IsInfinity(target)||target<.08||target>Scripts.MaxSeconds)throw new Exception("Khung chặng không hợp lệ.");original=original.Resample(24000);int frames=checked((int)Math.Round(target*24000));double min=Tempo.Minimum(o),max=Tempo.Maximum(o),speed=Math.Max(min,Math.Min(max,o.BaseSpeed*original.Duration/target));var best=new AnchorFit{Natural=original.Duration,Speed=speed,Measured=original.Duration};double error=Double.MaxValue;
  for(int attempt=0;attempt<8;attempt++){if(cancel())throw new OperationCanceledException();var wav=Tempo.Change(original,speed/o.BaseSpeed,root,work,cancel);if(o.RunReport!=null)o.RunReport.Attempt(speed,wav.Duration,target,"Căn toàn chặng; đo sau atempo, trước hiệu chỉnh đuôi");int delta=frames-wav.Samples.Length;if(Math.Abs(delta)<error){error=Math.Abs(delta);best.Audio=wav;best.Speed=speed;best.Measured=wav.Duration;}bool safeTail=delta>=0||Punctuation.EdgeSilence(wav,false)>=(-delta/24000.0+.003);if(Math.Abs(delta)<=480&&safeTail){var exact=new short[frames];Array.Copy(wav.Samples,exact,Math.Min(frames,wav.Samples.Length));best.Audio=new Wave{Rate=24000,Samples=exact};best.Success=true;best.Speed=speed;best.Measured=wav.Duration;best.SampleAdjustment=delta/24000.0;return best;}double correction=delta<0&&Math.Abs(delta)<=480&&!safeTail?.005:0;double next=Math.Max(min,Math.Min(max,speed*(wav.Duration+correction)/target));if(Math.Abs(next-speed)<.000001)break;speed=next;}
  double difference=best.Measured-target;best.Reason=(difference<0?"Thiếu ":"Dư ")+Math.Abs(difference).ToString("0.000")+"s sau khi căn; giới hạn "+min.ToString("0.00")+"–"+max.ToString("0.00")+". "+(difference<0?"Cần thêm lời hoặc đổi neo.":"Cần rút gọn lời hoặc đổi neo.");return best;
 }
 static Wave ReadStage(AnchorStage s,KokoroEngine e,RenderOptions o,BreathTrack breaths,string work,List<AnchorUnit> units){var parts=new PacedSpeech();var texts=SpeechUnits(s.Text);if(o.RunReport!=null)o.RunReport.PlanStageUnits(s.Number,texts);double cursor=0,tts=0,innerPauses=0,breathSeconds=0;Cue prior=null;Wave priorAudio=null;foreach(string text in texts){if(e.Cancelled)throw new OperationCanceledException();if(o.RunReport!=null)o.RunReport.BeginUnit(text,s.Number);if(o.RunReport!=null)o.RunReport.Step("TTS","Yêu cầu tổng hợp / lấy audio TTS");var paced=Punctuation.Generate(e,text,o.BaseSpeed,o,Path.Combine(work,"unit.wav"));if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Ghép lời với nghỉ trong đơn vị");var w=paced.Join();tts+=paced.SpeechSeconds;innerPauses+=Math.Max(0,w.Duration-paced.SpeechSeconds);if(o.RunReport!=null)o.RunReport.Natural(paced,w.Duration);double gapBefore=0,breathBefore=0;if(prior!=null){double pause=Math.Max(0,Math.Max(o.Gap,Punctuation.After(prior.Text,o))-Punctuation.EdgeSilence(priorAudio,false)-Punctuation.EdgeSilence(w,true));var breath=breaths.After(prior,24000);if(breath!=null){var mixed=new short[breath.Samples.Length];breaths.Mix(breath,priorAudio,mixed,0);parts.Pauses.Add(.04);parts.Parts.Add(new Wave{Rate=24000,Samples=mixed});parts.Pauses.Add(Math.Max(.04,pause-.04-breath.Duration));gapBefore=.04+breath.Duration+Math.Max(.04,pause-.04-breath.Duration);breathBefore=breath.Duration;breathSeconds+=breath.Duration;cursor+=gapBefore;breaths.Inserted(prior);}else{parts.Pauses.Add(pause);gapBefore=pause;cursor+=pause;}}
   if(o.RunReport!=null){o.RunReport.GapBefore(gapBefore,breathBefore);o.RunReport.UnitBeforeStageDone();}units.Add(new AnchorUnit{Stage=s.Number,Start=cursor,End=cursor+w.Duration,StageStart=s.Start,StageEnd=s.End,Text=text});parts.Parts.Add(w);cursor+=w.Duration;priorAudio=w;prior=new Cue{Text=text,Start=s.Start,End=s.Start+cursor};}if(prior!=null)breaths.After(prior,24000,0);if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Ghép toàn chặng với nghỉ và hơi thở");var joined=parts.Join();if(o.RunReport!=null)o.RunReport.StageComponents(tts,innerPauses,Math.Max(0,joined.Duration-tts-innerPauses-breathSeconds),breathSeconds,joined.Duration);return joined;}
 public static string Render(List<Cue> cues,KokoroEngine engine,RenderOptions o,string output,Action<int,string> progress){if(o.RunReport!=null)o.RunReport.Step("INPUT","Kiểm tra lời và chia chặng");var stages=Plan(cues);if(o.RunReport!=null){o.RunReport.PlanStages(stages);o.RunReport.Step("MODEL","Kiểm tra model/runtime/mẫu giọng");}engine.CheckFiles();if(o.RunReport!=null)o.RunReport.Step("INPUT","Kiểm tra thiết lập và đường dẫn xuất");Tempo.Validate(o);FinalAudio.Validate(o);Punctuation.Validate(o);if(!String.Equals(Path.GetExtension(output),".wav",StringComparison.OrdinalIgnoreCase))throw new Exception("Chỉ xuất WAV.");output=Path.GetFullPath(output);string parent=Path.GetDirectoryName(output);if(!Directory.Exists(parent))throw new DirectoryNotFoundException(parent);var report=new AnchorReport{Target=cues.Last().End};o.AnchorResult=report;if(o.AnchorChanged!=null)o.AnchorChanged(report);string tmp=Path.Combine(parent,".v15_anchor_"+Guid.NewGuid().ToString("N")+".tmp"),work=Path.Combine(Path.GetTempPath(),"V15_anchor_"+Guid.NewGuid().ToString("N")),oldContext=engine.RenderContext;
  try{if(o.RunReport!=null)o.RunReport.Step("SETUP","Chuẩn bị thư mục và hơi thở");Directory.CreateDirectory(work);var track=new BreathTrack(o,engine.Root);if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Mở WAV trung gian");using(var writer=new StreamingWave(tmp,24000)){foreach(var s in stages){if(engine.Cancelled)throw new OperationCanceledException();if(o.RunReport!=null)o.RunReport.BeginStage(s);engine.RenderContext=Path.GetFileName(output)+" · chặng "+s.Number+"/"+stages.Count;progress((s.Number-1)*85/stages.Count,"Đọc và căn chặng "+s.Number+"/"+stages.Count);var units=new List<AnchorUnit>();var natural=ReadStage(s,engine,o,track,work,units);if(o.RunReport!=null)o.RunReport.StageNatural(natural.Duration);if(o.RunReport!=null)o.RunReport.Step("FIT","Căn tốc độ toàn chặng");var fit=Fit(natural,s.Budget,o,engine.Root,work,()=>engine.Cancelled);if(o.RunReport!=null)o.RunReport.StageDone(s,fit);report.Stages.Add(new AnchorStageResult{Stage=s,Fit=fit});foreach(var c in s.Cues){c.Speed=fit.Speed;c.Natural=0;c.Actual=0;c.Status="Chặng "+s.Number+" · "+(fit.Success?"Đạt "+fit.Speed.ToString("0.000")+"x":fit.Reason);}
    if(fit.Success){if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Ghi chặng vào WAV trung gian");writer.At(s.Start,fit.Audio);double ratio=fit.Audio.Duration/natural.Duration;foreach(var u in units){u.Start=s.Start+u.Start*ratio;u.End=s.Start+u.End*ratio;report.Units.Add(u);}}if(o.AnchorChanged!=null)o.AnchorChanged(report);}
   if(o.RunReport!=null)o.RunReport.Step("FIT_RESULT","Kiểm tra kết quả căn toàn bộ chặng");if(report.Stages.Any(r=>!r.Fit.Success))throw new Exception("Chưa xuất WAV: có chặng ngoài giới hạn căn tốc độ.\r\n"+report.Describe());if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Hoàn tất WAV trung gian");writer.Finish(report.Target);}
   if(o.RunReport!=null)o.RunReport.Step("FORMAT","Kiểm tra định dạng và số mẫu WAV");long frames=(long)Math.Round(report.Target*24000);if(FinalAudio.PcmFrames(tmp)!=frames)throw new IOException("WAV không khớp thời lượng nguồn.");progress(90,"Kiểm tra thời lượng và hoàn thiện WAV");if(engine.Cancelled)throw new OperationCanceledException();if(o.NormalizeLoudness){if(o.RunReport!=null)o.RunReport.Step("NORMALIZE","Đo và cân âm lượng WAV");string norm=Path.Combine(work,"normalized.wav");FinalAudio.Normalize(engine.Root,tmp,norm,frames,o.TargetLufs,()=>engine.Cancelled,engine.ReportActivity);File.Copy(norm,tmp,true);}SubtitleDocument aligned=null;
   if(o.AnchorAlignment!=null)try{if(o.RunReport!=null)o.RunReport.Step("ALIGNMENT","Căn thêm SRT theo WAV");aligned=o.AnchorAlignment(tmp,report.Units);aligned.Validate();if(Math.Abs(aligned.Duration-report.Target)>.002)throw new Exception("SRT lệch tổng thời lượng.");foreach(var s in stages){var rows=aligned.Cues.Where(c=>c.Start>=s.Start-.001&&c.End<=s.End+.001).ToList();if(NormalizeText(String.Join(" ",rows.Select(c=>c.Text)))!=NormalizeText(s.Text))throw new Exception("SRT thiếu/đổi lời trong chặng "+s.Number);}if(aligned.Cues.Any(c=>!stages.Any(s=>c.Start>=s.Start-.001&&c.End<=s.End+.001)))throw new Exception("SRT vượt mốc chặng.");}catch(OperationCanceledException){throw;}catch(Exception ex){if(o.RunReport!=null)o.RunReport.ProcessFailure("SRT alignment",null,"",ex,false);aligned=null;report.AlignmentNote="WAV đã căn đủ; chưa tạo được SRT theo từ: "+ex.Message;}
   if(engine.Cancelled)throw new OperationCanceledException();if(o.RunReport!=null)o.RunReport.Step("PUBLISH","Lưu WAV cuối cạnh nguồn");report.Wav=OutputFiles.Publish(tmp,output);report.Complete=true;if(aligned!=null)try{report.Srt=aligned.ExportBeside(report.Wav);if(aligned.ReviewCount>0)report.AlignmentNote="SRT có "+aligned.ReviewCount+" khối cần nghe duyệt.";}catch(Exception ex){report.AlignmentNote="WAV đã xong; chưa lưu được SRT: "+ex.Message;}if(o.AnchorChanged!=null)o.AnchorChanged(report);progress(100,report.Summary);return report.Wav;
  }finally{engine.RenderContext=oldContext;try{File.Delete(tmp);}catch{}try{Directory.Delete(work,true);}catch{}}
 }
 static string NormalizeText(string text){return Regex.Replace(text??"",@"\s+"," ").Trim().ToLowerInvariant();}
}
}
